// Digital Product Studio - update script. Run from the project root (the folder that contains mcp, server and web).
// It backs up the old files into _backup_<time>/ and then writes the 10 updated files. It touches nothing else (.env and data are never read).
import fs from "node:fs"; import path from "node:path"; import zlib from "node:zlib";
const FILES = {"mcp/src/index.js":"","mcp/src/docbuilder.js":"","mcp/src/images.js":"","mcp/src/art.js":"","mcp/src/themes.js":"","mcp/src/store.js":"","mcp/src/pdf.js":"","server/src/agent.js":"","server/src/mcpClient.js":"","server/src/prompts/studio.md":""};
const root = process.cwd();
if (!fs.existsSync(path.join(root, "mcp", "src")) || !fs.existsSync(path.join(root, "server", "src"))) {
  console.error("Wrong folder. Open the terminal in the project root (the folder that contains 'mcp' and 'server') and run again."); process.exit(1);
}
const stamp = new Date().toISOString().replace(/[:.]/g, "-").slice(0, 19);
const bak = path.join(root, "_backup_" + stamp);
for (const [rel, b64] of Object.entries(FILES)) {
  const dest = path.join(root, ...rel.split("/"));
  if (fs.existsSync(dest)) { const b = path.join(bak, ...rel.split("/")); fs.mkdirSync(path.dirname(b), { recursive: true }); fs.copyFileSync(dest, b); }
  fs.mkdirSync(path.dirname(dest), { recursive: true });
  fs.writeFileSync(dest, zlib.gunzipSync(Buffer.from(b64, "base64")));
  console.log("updated  " + rel);
}
console.log("\nDone: " + Object.keys(FILES).length + " files. Old versions are in " + path.basename(bak) + ".\nNext: add OPENAI_API_KEY / GEMINI_API_KEY / SOFFICE_PATH to server/.env, stop the app and start it again.");
